from pycompss.api.task import task
from pycompss.api.api import compss_wait_on

@task(returns=list)
def compute_row(A_row, B):
    N = len(B[0])
    K = len(B)
    row_result = []
    for j in range(N):
        val = 0
        for k in range(K):
            val += A_row[k] * B[k][j]
        row_result.append(val)
    return row_result

def main(A, B):
    M = len(A)
    tasks = [compute_row(A[i], B) for i in range(M)]

    return compss_wait_on(tasks)
